import{_ as l,C as r,o as p,c as g,a3 as a,j as s,E as e,a as n,w as h}from"./chunks/framework.DCn7xQd4.js";const d="/versions/v0.19.16/screens/routing/param_options_in_snapshot_off.png",T=JSON.parse('{"title":"Snapshots","description":"","frontmatter":{},"headers":[],"relativePath":"snapshots/index.md","filePath":"snapshots/index.md"}'),u={name:"snapshots/index.md"};function m(f,t,S,c,A,N){const o=r("C"),i=r("ManualRelated");return p(),g("div",null,[t[16]||(t[16]=a('<h1 id="snapshots" tabindex="-1">Snapshots <a class="header-anchor" href="#snapshots" aria-label="Permalink to &quot;Snapshots&quot;">​</a></h1><p>A snapshot is a <strong>scene</strong> inside the active project — a stored set of live values you can recall during a set.</p><p>This firmware has three live banks, and each one has <strong>one door</strong> — you open it from wherever that part already lives. <strong>Main Menu → ARRANGE</strong> (first item) is the song grid.</p><p><strong><a href="./knob-bank">Knob snapshots</a></strong> — <strong>Main Menu → Snapshots</strong> opens the 4×8 slot grid (header <strong>Knobs Snapshots</strong>). Occupied Select glides live to that pad when <strong>this bank&#39;s FADE TIME</strong> is on, or lands instantly when it is <strong>OFF</strong>. Hold Select and turn the encoder to morph by hand. Select+Back toggles <strong>BANK</strong> and the <strong>pencil</strong>. Long-press on BANK: take, rename, delete, copy, swap, move. <strong>MAPPING</strong> and <strong>SYNC</strong> are on the pencil tab.</p><p><strong><a href="./rack-bank">Rack snapshots</a></strong> — Racks list → <strong>Long-press Select</strong> → <strong>SNAPSHOTS BANK</strong> opens that rack&#39;s 4×8 (<strong>Rack 1 Snapshots</strong>…<strong>Rack 8 Snapshots</strong>).</p><p><strong><a href="./lfo-bank">LFO snapshots</a></strong> — S32 LFO grid → <strong>Long-press Select</strong> → <strong>SNAPSHOTS BANK</strong> opens the 4×8 (<strong>LFOs Snapshots</strong>).</p><p><strong><a href="./studio">Open a snapshot bank</a></strong> — All three doors side by side, and where <strong>Back</strong> goes from each pad.</p><p><strong><a href="./lanes">Arrange</a></strong> — <strong>ARRANGE</strong> on Main Menu (above Racks). <strong>SONG</strong> is a grid of 4–256 rows (default 16) × 10 columns; the <strong>pencil</strong> tab is Arrange, Rate, Fade Time, Repeat, Length, Jump To, Queue. Playhead recalls use Fade Time; Jump To and Queue stay instant.</p><p><strong><a href="./morph">Morph</a></strong> — Occupied <strong>Select</strong> (and MIDI / SNAP-macro) glides live to that pad using <strong>this bank&#39;s FADE TIME</strong>. The Arrange <strong>playhead</strong> uses <strong>Arrange FADE TIME</strong>. Another occupied pad retargets. Empty pads <strong>TAKE</strong>. <strong>MAP MORPH</strong> is a fader from live to the current snapshot (0% what you are hearing, 100% that scene).</p><h2 id="keep-one-parameter-under-your-hands" tabindex="-1">Keep one parameter under your hands <a class="header-anchor" href="#keep-one-parameter-under-your-hands" aria-label="Permalink to &quot;Keep one parameter under your hands&quot;">​</a></h2><p>Some controls you want to own live — a filter cutoff you ride by hand, an LFO rate you nudge with the tempo. Take that parameter out of snapshots entirely:</p>',11)),s("ol",null,[s("li",null,[e(o,{action:"encoder-turn"}),t[0]||(t[0]=n()),t[1]||(t[1]=s("strong",null,"Encoder",-1)),t[2]||(t[2]=n(" — highlight the parameter in a device parameter list or an LFO parameter list.",-1))]),s("li",null,[e(o,{action:"select-long"}),t[3]||(t[3]=n()),t[4]||(t[4]=s("strong",null,"Long-press Select",-1)),t[5]||(t[5]=n(" → ",-1)),t[6]||(t[6]=s("strong",null,"Options",-1)),t[7]||(t[7]=n(".",-1))]),s("li",null,[e(o,{action:"select"}),t[8]||(t[8]=n()),t[9]||(t[9]=s("strong",null,"Select",-1)),t[10]||(t[10]=n(" the third row, ",-1)),t[11]||(t[11]=s("strong",null,"IN SNAPSHOT ON",-1)),t[12]||(t[12]=n(". It flips to ",-1)),t[13]||(t[13]=s("strong",null,"IN SNAPSHOT OFF",-1)),t[14]||(t[14]=n(" and stays on screen, so you can see the state without leaving the menu.",-1))])]),t[17]||(t[17]=a('<p><img src="'+d+'" alt="Parameter Options with IN SNAPSHOT OFF" class="screen"></p><p>While a parameter reads <strong>IN SNAPSHOT OFF</strong>, no recall on any bank or slot moves it. Neither does a <strong>this bank&#39;s FADE TIME</strong> glide, an <strong>Arrange FADE TIME</strong> playhead glide, or a <strong>morph</strong> — not even at 0% or 100%. It stays exactly where you left it.</p><p>The setting lives on the parameter, not on a slot, and it saves with the project. Every parameter starts at <strong>IN SNAPSHOT ON</strong>.</p><p>When <strong>IN SNAPSHOT</strong> is <strong>ON</strong>, <strong>ALLOW MORPH YES</strong> sits on the next row. Flip it to <strong>ALLOW MORPH NO</strong> so that parameter stays live during a fade or morph and only jumps to the snapshot at <strong>100%</strong>. The row hides when <strong>IN SNAPSHOT</strong> is <strong>OFF</strong>, and it is not shown for channel, port, note, MIDI type, per-step, or pattern fields. Bypass, sync, mode, and scale start at <strong>NO</strong>. Rate, depth, offset, ranged values, and LFO wave start at <strong>YES</strong>. Wave type still steps from one shape to the next — it does not crossfade tables.</p><p><strong>If a knob is mapped to it,</strong> a knob snapshot still moves the knob to its stored position — that position is part of the scene, and anything else the same knob drives still follows it. The parameter you set aside is the one thing that does not move, so the knob and that parameter can read differently until you next touch it.</p><p><strong>TAKE still stores the value.</strong> Turning the flag back on restores normal recall from snapshots you already took — nothing is lost while it is off. Duplicating a device carries its flags across.</p><p>This is finer than <strong>INCLUDE</strong>, which switches whole knobs macros, LFOs, or devices per slot. The two work together: a recall moves a parameter only when its slot includes that group <strong>and</strong> the parameter reads <strong>IN SNAPSHOT ON</strong>.</p><p>Use <a href="./../projects/">Save Project</a> for lasting structure (devices, macros, LFO wiring).</p>',8)),e(i,null,{default:h(()=>[...t[15]||(t[15]=[s("ul",null,[s("li",null,[s("a",{href:"./studio"},"Open a snapshot bank"),n(" — One door per bank")]),s("li",null,[s("a",{href:"./knob-bank"},"Knob snapshots"),n(" — 4×8 pad from Main Menu")]),s("li",null,[s("a",{href:"./rack-bank"},"Rack snapshots"),n(" — 4×8 pad from SNAPSHOTS BANK")]),s("li",null,[s("a",{href:"./lfo-bank"},"LFO snapshots"),n(" — 4×8 pad from SNAPSHOTS BANK")]),s("li",null,[s("a",{href:"./morph"},"Morph"),n(" — Live to a pad with this bank's FADE TIME")]),s("li",null,[s("a",{href:"./lanes"},"Arrange"),n(" — SONG / pencil")]),s("li",null,[s("a",{href:"./../concepts/projects-and-snapshots"},"Projects & snapshots concept"),n(" — Projects vs snapshots")]),s("li",null,[s("a",{href:"./../projects/"},"Projects"),n(" — Save and load projects")])],-1)])]),_:1})])}const k=l(u,[["render",m]]);export{T as __pageData,k as default};
